            Title = "Work Centers and Routings",
            Slug = "manufacturing-overview",
            Summary = "The two pieces of setup every made part depends on: the work centers your shop runs, and the routing that says which steps a part goes through and how long each takes",
            ContentType = TrainingContentType.Article,
