            ContentJson = """{"title":"Manufacturing Field Reference","groups":[{"heading":"Work center dialog (Scheduling > Work Centers)","items":[{"label":"Code / Name","value":"Short code and display name, for example CNC1 / CNC Mill 1."},{"label":"Description","value":"Free text. Optional."},{"label":"Daily Capacity (hours)","value":"Hours of work the center can take in one day. The scheduler will not load more than this before pushing work to the next day."},{"label":"Efficiency %","value":"Share of capacity that becomes real output. 85 means 8 hours of capacity yields about 6.8 hours of work."},{"label":"Number of Machines","value":"Parallel machines on the center. Multiplies throughput."},{"label":"Labor Cost / Hour","value":"Wage cost of an hour on this center. Feeds the job's estimated labor cost."},{"label":"Burden Rate / Hour","value":"Overhead per hour on this center. Feeds estimated burden unless departmental overhead rates are switched on in Costing."},{"label":"Assigned Asset","value":"Optional link to the physical machine in Assets."},{"label":"Sort Order","value":"Position in lists and pickers."},{"label":"Active","value":"Off retires the center: hidden from routing and scheduling choices, history kept."}]},{"heading":"Operation dialog (part Routing tab)","items":[{"label":"Step number","value":"Run order. Drag the cards on the Routing tab to reorder."},{"label":"Title","value":"Short name of the step, for example Rough turn."},{"label":"Work center","value":"Where the step runs. New work center creates one without leaving the dialog."},{"label":"Estimated time","value":"Hours, minutes and milliseconds per operation. Basis for scheduling, labor estimate and efficiency."},{"label":"Instructions","value":"What the operator does. Shown wherever the operation is worked."},{"label":"Materials / BOM Line","value":"Which BOM lines the step consumes. Add BOM lines to the part first."},{"label":"QC Checkpoint","value":"Marks the step as an inspection point."},{"label":"QC Pass/Fail Criteria","value":"What the inspector checks. Shown with the checkpoint."},{"label":"Subcontract Operation","value":"The step is done by an outside vendor."},{"label":"Vendor","value":"The subcontractor. Shown as (no vendor) on the card until one is chosen."},{"label":"Turn Time (days)","value":"Round-trip days at the vendor. The schedule allows for it."},{"label":"References Operation","value":"Reuse another operation's definition for this step."}]},{"heading":"Routing tab (part)","items":[{"label":"List / Flow","value":"View the operations as cards or as a flow diagram."},{"label":"Add operation","value":"Opens the operation dialog with the next step number."},{"label":"Reorder","value":"Drag a card to a new position; Forge renumbers the steps."}]},{"heading":"Dispatch List (Scheduling > Dispatch)","items":[{"label":"Job #","value":"The job the operation belongs to."},{"label":"Operation","value":"The routing step title."},{"label":"Work Center","value":"Where it runs. Filterable, so you can see one center's queue."},{"label":"Start / End","value":"Scheduled start and end from the last scheduling run."},{"label":"Hours","value":"Scheduled hours for the operation."},{"label":"Status","value":"Scheduled, In Progress or Complete."},{"label":"Locked","value":"A locked operation keeps its slot when the schedule is re-run."}]},{"heading":"Job detail: release","items":[{"label":"BOM revision at release","value":"The bill of materials revision the job was created against. A warning appears if the BOM has changed since."},{"label":"Explode BOM","value":"Creates a child job for each made sub-assembly on the BOM, linked under this job."},{"label":"Sub-Jobs","value":"Child jobs created by Explode BOM or by hand."},{"label":"Parts","value":"The part or parts this job makes."}]},{"heading":"Job detail: Operation Time","items":[{"label":"#","value":"Operation sequence."},{"label":"Operation","value":"The routing step."},{"label":"Estimated","value":"Hours from the routing."},{"label":"Actual","value":"Hours logged against this operation by operators."},{"label":"Efficiency","value":"Estimated divided by actual. Under 100 percent means the step ran long."}]},{"heading":"Job detail: Cost Analysis","items":[{"label":"Category","value":"Material, Labor, Burden, Subcontract and Total."},{"label":"Estimated","value":"Cost set at release from the BOM, routing and work center rates."},{"label":"Actual","value":"Cost from material issues, time entries and subcontract charges."},{"label":"Variance","value":"Actual minus Estimated. Positive is over plan. The total also shows a percentage."},{"label":"Quoted Price / Actual Margin","value":"What the customer was quoted and what is left after actual cost."},{"label":"Recalculate costs","value":"Rebuilds the summary from the underlying issues and time entries."}]},{"heading":"Material Issues list","items":[{"label":"Part # / Description","value":"The material charged to the job."},{"label":"Qty / Unit Cost / Total","value":"Quantity, cost per unit at the time of issue, and the extended amount."},{"label":"Type","value":"Issue (pulled for the job), Return (sent back to stock) or Scrap (consumed and lost)."},{"label":"Date","value":"When the issue was recorded."},{"label":"Return","value":"On an Issue line: writes a Return for the same quantity and puts it back in inventory."}]}]}"""
        });

